# Expected values generated by test/scipy/gen_optimize_constrained_expected.py (scipy 1.18.1).
# Constrained minimization: SLSQP, trust-constr, COBYLA with dict-style,
# LinearConstraint and NonlinearConstraint constraints and Bounds (HS071,
# constrained Rosenbrock, Nocedal-Wright 16.4 example).
import numpy as np
import scipy.optimize as so
from scipy.optimize import LinearConstraint, NonlinearConstraint, Bounds

def close(x, ref, rtol: float = 1e-7, atol: float = 1e-10) -> bool:
    a = np.asarray(x, float)
    r = np.asarray(ref, float)
    if a.size != r.size:
        print('size', a.size, r.size)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def f2(x):
    return (x[0] - 1.0) ** 2 + (x[1] - 2.5) ** 2

def g1(x):
    return x[0] - 2 * x[1] + 2

def g2(x):
    return -x[0] - 2 * x[1] + 6

def g3(x):
    return -x[0] + 2 * x[1] + 2

CONS3 = ({'type': 'ineq', 'fun': g1}, {'type': 'ineq', 'fun': g2},
         {'type': 'ineq', 'fun': g3})

def hs(x):
    return x[0] * x[3] * (x[0] + x[1] + x[2]) + x[2]

def hsg(x):
    return np.array([x[0] * x[3] + x[3] * (x[0] + x[1] + x[2]), x[0] * x[3],
                     x[0] * x[3] + 1.0, x[0] * (x[0] + x[1] + x[2])])

def hs_ineq(x):
    return np.array([x[0] * x[1] * x[2] * x[3] - 25.0])

def hs_eq(x):
    return np.array([x[0] ** 2 + x[1] ** 2 + x[2] ** 2 + x[3] ** 2 - 40.0])

HS_C = ({'type': 'ineq', 'fun': hs_ineq}, {'type': 'eq', 'fun': hs_eq})
HSB = Bounds(np.ones(4), 5 * np.ones(4))
HSX0 = np.array([1.0, 5.0, 5.0, 1.0])
HSX = [1.0, 4.742996, 3.821150, 1.379408]

def cf(x):
    return np.array([x[0] ** 2 + x[1], x[0] ** 2 - x[1]])

def cj(x):
    return np.array([[2 * x[0], 1.0], [2 * x[0], -1.0]])

def ch(x, v):
    return v[0] * np.array([[2.0, 0.0], [0.0, 0.0]]) + v[1] * np.array([[2.0, 0.0], [0.0, 0.0]])

LC = LinearConstraint([[1.0, 2.0], [2.0, 1.0]], [-np.inf, 1.0], [1.0, 1.0])
NC = NonlinearConstraint(cf, -np.inf, 1.0, jac=cj, hess=ch)
RB = Bounds([0.0, -0.5], [1.0, 2.0])
RX = [0.4149453134150196, 0.17010937316996083]

def eq1(x):
    return np.array([x[0] + x[1] - 1.0])

def test_slsqp():
    r = so.minimize(f2, np.array([2.0, 0.0]), method='SLSQP',
                    bounds=((0.0, None), (0.0, None)), constraints=CONS3)
    check(close(r.x, [1.400000003383427, 1.7000000009466523], 1e-8), 'slsqp a x')
    check(r.nit == 3 and r.nfev == 10 and r.njev == 3 and r.status == 0, 'slsqp a counts')
    check(r.message == 'Optimization terminated successfully', 'slsqp message')
    check(r.multipliers.size == 3, 'slsqp multipliers')
    # default method with constraints is SLSQP
    r = so.minimize(hs, HSX0, jac=hsg, bounds=HSB, constraints=HS_C)
    check(close(r.x, [1.0, 4.742996049948936, 3.8211546847463693, 1.379407636579196], 1e-6), 'hs071 slsqp x')
    check(abs(r.fun - 17.014017245579602) < 1e-8, 'hs071 slsqp fun')
    check(r.nit == 5 and r.nfev == 5 and r.njev == 5, 'hs071 slsqp counts')
    r = so.minimize(so.rosen, np.array([0.5, 0.0]), method='SLSQP', jac=so.rosen_der,
                    constraints=(LC, NC), bounds=RB)
    check(close(r.x, [0.41494474917025453, 0.17011050165949088], 1e-6), 'slsqp rosen x')
    check(r.nit == 4 and r.nfev == 5 and r.njev == 4, 'slsqp rosen counts')

def test_trust_constr():
    r = so.minimize(so.rosen, np.array([0.5, 0.0]), method='trust-constr',
                    jac=so.rosen_der, hess=so.rosen_hess, constraints=(LC, NC), bounds=RB)
    check(close(r.x, RX, 1e-8), 'tc doc x')
    check(r.nit == 12 and r.nfev == 8 and r.njev == 8 and r.cg_niter == 7, 'tc doc counts')
    check(r.status == 1 and r.success and r.method == 'tr_interior_point', 'tc doc status')
    check(r.constr_violation == 0.0 and len(r.constr) == 3, 'tc doc constr')
    r = so.minimize(so.rosen, np.array([0.5, 0.0]), method='trust-constr',
                    jac=so.rosen_der, hess=so.SR1(),
                    constraints=(LC, NonlinearConstraint(cf, -np.inf, 1.0)), bounds=RB)
    check(close(r.x, [0.4149453135006091, 0.1701093729987819], 1e-7), 'tc sr1 x')
    check(r.nit == 12 and r.nfev == 8 and r.njev == 8, 'tc sr1 counts')
    r = so.minimize(so.rosen, np.array([0.5, 0.0]), method='trust-constr',
                    jac=so.rosen_der, hess=so.rosen_hess)
    check(close(r.x, [0.9999999991173122, 0.9999999982310964], 1e-8), 'tc unc x')
    check(r.nit == 16 and r.nfev == 16 and r.cg_niter == 25, 'tc unc counts')
    check(r.method == 'equality_constrained_sqp', 'tc unc method')
    r = so.minimize(so.rosen, np.array([0.5, 0.0]), method='trust-constr',
                    jac=so.rosen_der, hess=so.rosen_hess,
                    constraints=({'type': 'eq', 'fun': eq1},))
    check(close(r.x, [0.6187956190753835, 0.38120438092461645], 1e-8), 'tc eq x')
    check(r.nit == 6 and r.nfev == 6, 'tc eq counts')
    r = so.minimize(hs, HSX0, method='trust-constr', jac=hsg, bounds=HSB, constraints=HS_C)
    check(close(r.x, HSX, 1e-5), 'hs071 tc x')
    check(abs(r.fun - 17.014017392470855) < 1e-6 and r.status == 1, 'hs071 tc fun')
    # iteration count drifts slightly with BLAS rounding (scipy: 75)
    check(abs(r.nit - 75) <= 5, 'hs071 tc nit')
    r = so.minimize(f2, np.array([2.0, 0.0]), method='trust-constr', constraints=CONS3)
    check(close(r.x, [1.399986640533896, 1.6999733184911272], 1e-5), 'tc a x')
    check(abs(r.nit - 14) <= 1 and r.status == 1, 'tc a nit')

def test_cobyla():
    r = so.minimize(f2, np.array([2.0, 0.0]), method='COBYLA', constraints=CONS3)
    check(close(r.x, [1.3999939199075813, 1.6999969599537903], 1e-9), 'cobyla a x')
    check(r.nfev == 32 and r.status == 0 and r.success, 'cobyla a counts')
    check(r.maxcv == 0.0, 'cobyla maxcv')
    check(r.message == 'Return from COBYLA because the trust region radius reaches its lower bound.', 'cobyla message')
    r = so.minimize(so.rosen, np.array([0.5, 0.0]), method='COBYLA', constraints=(LC, NC), bounds=RB)
    check(close(r.x, RX, 1e-4), 'cobyla rosen x')
    check(abs(r.nfev - 30) <= 3, 'cobyla rosen nfev')
    r = so.minimize(hs, HSX0, method='COBYLA', bounds=HSB, constraints=HS_C)
    check(close(r.x, HSX, 2e-3), 'hs071 cobyla x')
    check(abs(r.fun - 17.014019852195684) < 1e-4, 'hs071 cobyla fun')

test_trust_constr()
print('done')
